package de.luckymcdev.foundryengine.common.script.sandbox;

import java.util.List;
import java.util.Set;

/**
 * The deny lists. Single source of truth for the class loader filter and the AST checks.
 */
final class SandboxRules {

	/**
	 * Matched by simple name, so imports and fully qualified use are both caught.
	 */
	static final Set<String> DENIED_ANNOTATIONS = Set.of(
		"ASTTest", "Grab", "Grapes", "GrabResolver", "GrabConfig", "GrabExclude"
	);

	/**
	 * Denied when a script class is linked. Must NOT contain anything Groovy-generated bytecode
	 * references itself (java.lang.Thread for interrupt checks, groovy.lang.MetaClass,
	 * org.codehaus.groovy.runtime.callsite.*, ...).
	 */
	private static final Set<String> RUNTIME_DENIED_CLASSES = Set.of(
		"java.lang.Runtime",
		"java.lang.ProcessBuilder",
		"java.lang.Process",
		"java.lang.ProcessHandle",
		"java.lang.Compiler",
		"java.lang.ClassLoader",
		"java.util.zip.ZipFile",
		"java.util.jar.JarFile",
		"java.util.logging.FileHandler",
		"java.awt.Desktop",
		"java.awt.Robot",
		"groovy.lang.GroovyShell",
		"groovy.lang.GroovyClassLoader",
		"groovy.lang.ExpandoMetaClass",
		"groovy.lang.MetaClassRegistry",
		"groovy.lang.GroovySystem",
		"groovy.util.Eval",
		"groovy.util.GroovyScriptEngine"
	);

	private static final List<String> RUNTIME_DENIED_PREFIXES = List.of(
		"java.io.",
		"java.net.",
		"java.nio.file.",
		"java.nio.channels.",
		"java.lang.reflect.",
		"java.lang.invoke.",
		"java.lang.foreign.",
		"java.lang.module.",
		"java.util.prefs.",
		"java.rmi.",
		"javax.script.",
		"javax.naming.",
		"javax.management.",
		"javax.net.",
		"javax.tools.",
		"sun.",
		"com.sun.",
		"jdk.",
		"org.codehaus.groovy.control.",
		"org.codehaus.groovy.tools.",
		"org.spongepowered.",
		"org.objectweb.asm.",
		"net.neoforged.fml.loading.",
		"cpw.mods."
	);

	/**
	 * Additionally denied in source (imports, types, constructors, receivers), but fine at link time.
	 */
	private static final Set<String> COMPILE_ONLY_DENIED_CLASSES = Set.of(
		"java.lang.Thread",
		"java.lang.ThreadGroup",
		"java.lang.SecurityManager",
		"java.lang.System",
		"org.codehaus.groovy.runtime.InvokerHelper",
		"org.codehaus.groovy.runtime.ProcessGroovyMethods",
		"org.codehaus.groovy.runtime.DefaultGroovyMethods"
	);

	/**
	 * Method names denied on ANY receiver (receiver types are unknown in dynamic Groovy).
	 */
	private static final Set<String> DENIED_METHODS = Set.of(
		"getClassLoader", "getContextClassLoader", "forName", "loadClass", "defineClass",
		"getMetaClass", "setMetaClass", "invokeMethod", "getProperty", "setProperty",
		"getDeclaredMethod", "getDeclaredMethods", "getMethod", "getMethods",
		"getDeclaredField", "getDeclaredFields", "getField", "getFields",
		"getDeclaredConstructor", "getDeclaredConstructors", "getConstructor", "getConstructors",
		"getRecordComponents", "setAccessible", "trySetAccessible", "getProtectionDomain",
		"getModule", "getResource", "getResources", "getResourceAsStream",
		"execute", "evaluate", "toURL", "waitFor"
	);

	/**
	 * Property names denied on ANY receiver (explicit getter calls are covered by DENIED_METHODS).
	 */
	private static final Set<String> DENIED_PROPERTIES = Set.of(
		"classLoader", "contextClassLoader", "metaClass", "protectionDomain",
		"declaredMethods", "methods", "declaredFields", "fields",
		"declaredConstructors", "constructors", "recordComponents"
	);

	private SandboxRules() {
	}

	/**
	 * Link-time check, used by the filtering class loader.
	 */
	static boolean isRuntimeDenied(String className) {
		if (className.isEmpty() || className.startsWith("[")) {
			return false;
		}
		return RUNTIME_DENIED_CLASSES.contains(className) || hasDeniedPrefix(className);
	}

	/**
	 * Source-level check for fully qualified type or package names (a package ends with '.').
	 */
	static boolean isSourceTypeDenied(String name) {
		return RUNTIME_DENIED_CLASSES.contains(name)
			|| COMPILE_ONLY_DENIED_CLASSES.contains(name)
			|| hasDeniedPrefix(name);
	}

	static boolean isMethodDenied(String name) {
		return DENIED_METHODS.contains(name);
	}

	static boolean isPropertyDenied(String name) {
		return DENIED_PROPERTIES.contains(name);
	}

	private static boolean hasDeniedPrefix(String name) {
		for (String prefix : RUNTIME_DENIED_PREFIXES) {
			if (name.startsWith(prefix)) {
				return true;
			}
		}
		return false;
	}
}